mapper.insert:
insert into visitor_application(
    application_id, visitor_id, host_id, host_name, start_time, end_time, reason, status, create_time
) values (
    #{applicationId}, #{visitorId}, #{hostId}, #{hostName}, #{startTime}, #{endTime}, #{reason}, '0', #{createTime}
)

mapper.select:
select count(1) from visitor_application
where visitor_id = #{visitorId}
  and status = '2'
  and approve_time is not null
  and approve_time >= #{todayStart}
  and approve_time < #{nextDayStart}

mapper.update:
update visitor_application
set status = #{status}, approve_time = #{approveTime}, update_time = #{updateTime}
where application_id = #{applicationId} and status = '0'
